<?php
$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));$cat=(int)($_GET['category']??0);$method=(string)($_GET['method']??'');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');if($from>$to){[$from,$to]=[$to,$from];}
$where=' WHERE DATE(o.created_at) BETWEEN ? AND ? AND o.status<>\'Dibatalkan\'';$args=[$from,$to];if($method&&in_array($method,['Tunai','QRIS','Transfer Bank','Kartu Debit'],true)){$where.=' AND o.payment_method=?';$args[]=$method;}if($cat){$where.=' AND EXISTS(SELECT 1 FROM order_details d JOIN products p ON p.id=d.product_id WHERE d.order_id=o.id AND p.category_id=?)';$args[]=$cat;}if(!is_admin()){$where.=' AND o.user_id=?';$args[]=current_user()['id'];}
$query='SELECT o.*,u.full_name cashier,(SELECT GROUP_CONCAT(CONCAT(d.product_name,\' ×\',d.quantity) ORDER BY d.id SEPARATOR \' · \') FROM order_details d WHERE d.order_id=o.id) item_list,(SELECT COALESCE(SUM(d.unit_cost*d.quantity),0) FROM order_details d WHERE d.order_id=o.id) cost_total FROM orders o JOIN users u ON u.id=o.user_id'.$where.' ORDER BY o.created_at DESC';$s=db()->prepare($query);$s->execute($args);$rows=$s->fetchAll();
$gross=array_sum(array_column($rows,'subtotal'));$discountTotal=array_sum(array_column($rows,'discount_amount'));$taxTotal=array_sum(array_column($rows,'tax_amount'));$net=array_sum(array_column($rows,'grand_total'));$avg=count($rows)?round($net/count($rows)):0;$profit=array_sum(array_map(fn($r)=>max(0,(int)$r['subtotal']-(int)$r['discount_amount']-(int)$r['cost_total']),$rows));
if(($_GET['export']??'')==='csv'){$filename='laporan-ruang-seduh-'.$from.'-'.$to.'.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['No. Faktur','Tanggal & Jam','Kasir','Tipe Pesanan','Item Terjual','Subtotal','Pajak','Grand Total','Status','Metode Pembayaran'], ';');foreach($rows as $r)fputcsv($out,[$r['invoice_number'],$r['created_at'],$r['cashier'],$r['order_type'],$r['item_list'],$r['subtotal'],$r['tax_amount'],$r['grand_total'],$r['status'],$r['payment_method']],';');fclose($out);exit;}
?>
<div class="page-heading"><div><p class="eyebrow">ANALISIS PENJUALAN</p><h1>Laporan penjualan</h1><p class="subheading">Telusuri transaksi dan unduh rekap sesuai kebutuhan.</p></div><div class="export-actions"><a class="button quiet" href="<?= e('index.php?'.http_build_query(['page'=>'reports','from'=>$from,'to'=>$to,'category'=>$cat,'method'=>$method,'export'=>'csv'])) ?>">↓ Ekspor CSV</a><button class="button quiet" onclick="window.print()">▤ Simpan PDF</button></div></div>
<section class="panel report-filter"><form method="get" id="report-filter"><input type="hidden" name="page" value="reports"><label>Dari tanggal<input type="date" name="from" value="<?= e($from) ?>"></label><label>Sampai tanggal<input type="date" name="to" value="<?= e($to) ?>"></label><label>Kategori menu<select name="category"><option value="0">Semua kategori</option><?php foreach(categories() as $c):?><option value="<?= (int)$c['id'] ?>" <?= $cat===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach;?></select></label><label>Metode pembayaran<select name="method"><option value="">Semua metode</option><?php foreach(['Tunai','QRIS','Transfer Bank','Kartu Debit'] as $m):?><option <?= $method===$m?'selected':'' ?>><?= e($m) ?></option><?php endforeach;?></select></label><button class="button primary" type="submit">Terapkan filter</button></form></section>
<div class="report-summary"><article><span>Omset bruto</span><strong><?= rupiah($gross) ?></strong><small>Subtotal menu terjual</small></article><article><span>Diskon diberikan</span><strong><?= rupiah($discountTotal) ?></strong><small>Potongan pada transaksi</small></article><article><span>Pajak terkumpul</span><strong><?= rupiah($taxTotal) ?></strong><small>PB1 restoran 10%</small></article><article><span>Laba kotor</span><strong><?= rupiah($profit) ?></strong><small>Setelah diskon dan harga pokok</small></article><article class="summary-net"><span>Omset bersih</span><strong><?= rupiah($net) ?></strong><small><?= count($rows) ?> transaksi · rata-rata <?= rupiah($avg) ?></small></article></div>
<section class="panel report-table-panel"><div class="panel-heading"><div><h2>Rincian transaksi</h2><p><?= date('d M Y',strtotime($from)) ?> — <?= date('d M Y',strtotime($to)) ?> · <?= count($rows) ?> transaksi</p></div></div><div class="table-scroll"><table><thead><tr><th>No. faktur</th><th>Tanggal & jam</th><th>Kasir</th><th>Tipe pesanan</th><th>Item terjual</th><th>Subtotal</th><th>Pajak</th><th>Grand total</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $o):?><tr><td><a class="invoice-link" href="index.php?page=receipt&id=<?= (int)$o['id'] ?>"><?= e($o['invoice_number']) ?></a></td><td><?= date('d/m/y H:i',strtotime($o['created_at'])) ?></td><td><?= e($o['cashier']) ?></td><td><?= e($o['order_type']) ?></td><td class="item-list-cell"><?= e($o['item_list']?:'—') ?></td><td><?= rupiah($o['subtotal']) ?></td><td><?= rupiah($o['tax_amount']) ?></td><td class="money-cell"><?= rupiah($o['grand_total']) ?></td><td><span class="status <?= $o['status']==='Selesai'?'done':'pending' ?>"><?= e($o['status']) ?></span></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty-state"><span>▥</span><strong>Tidak ada transaksi pada rentang ini</strong><p>Ubah filter tanggal atau kategori untuk melihat hasil lainnya.</p></div><?php endif;?></div></section>
